import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"MySQL和HTTPS配置","description":"","frontmatter":{"title":"MySQL和HTTPS配置","author":"麻瓜【码瓜】","date":"2024-07-04"},"headers":[],"relativePath":"posts/mysqlandhttps.md","filePath":"posts/mysqlandhttps.md","lastUpdated":1794582610000}'),o={name:"posts/mysqlandhttps.md"};function n(c,a,d,l,p,r){return t(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="mysql和https配置" tabindex="-1">MySQL和HTTPS配置 <a class="header-anchor" href="#mysql和https配置" aria-label="Permalink to &quot;MySQL和HTTPS配置&quot;">​</a></h1><h2 id="mysql无法远程连接" tabindex="-1">MySQL无法远程连接 <a class="header-anchor" href="#mysql无法远程连接" aria-label="Permalink to &quot;MySQL无法远程连接&quot;">​</a></h2><p>修改配置文件<code>/etc/mysql/mysql.conf.d/mysqld.cnf</code>，将<code>bind-address = 127.0.0.1</code>注释掉</p><h2 id="备份数据库" tabindex="-1">备份数据库 <a class="header-anchor" href="#备份数据库" aria-label="Permalink to &quot;备份数据库&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysqldump -u root -p  [DATABASE_NAME] &gt; ./[DATABASE_NAME].sql</span></span></code></pre></div><h2 id="恢复数据库" tabindex="-1">恢复数据库 <a class="header-anchor" href="#恢复数据库" aria-label="Permalink to &quot;恢复数据库&quot;">​</a></h2><h3 id="方法一" tabindex="-1">方法一 <a class="header-anchor" href="#方法一" aria-label="Permalink to &quot;方法一&quot;">​</a></h3><p>进入对应的数据库</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use [DATABASE_NAME];</span></span></code></pre></div><p>恢复数据库</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source /var/bak/[DATABASE_NAME].sql;</span></span></code></pre></div><h3 id="方法二" tabindex="-1">方法二 <a class="header-anchor" href="#方法二" aria-label="Permalink to &quot;方法二&quot;">​</a></h3><p>直接在bash界面下操作</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysql -u root -p [DATABASE_NAME] &lt; ./[DATABASE_NAME].sql</span></span></code></pre></div><h2 id="https配置" tabindex="-1">HTTPS配置 <a class="header-anchor" href="#https配置" aria-label="Permalink to &quot;HTTPS配置&quot;">​</a></h2><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apt install -y certbot python3-certbot-nginx</span></span></code></pre></div><h3 id="部署" tabindex="-1">部署 <a class="header-anchor" href="#部署" aria-label="Permalink to &quot;部署&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>certbot --nginx -d domain.com -d www.domain.com</span></span></code></pre></div><p>返回如下信息即成功：<br><code>Successfully received certificate.</code><br><code>Certificate is saved at: /etc/letsencrypt/live/domain.com/fullchain.pem</code><code>Key is saved at: /etc/letsencrypt/live/domain.com/privkey.pem</code><br><code>This certificate expires on 2024-09-08.</code><br><code>These files will be updated when the certificate renews.</code><br><code>Certbot has set up a scheduled task to automatically renew this certificate in the background.</code><br><code>Deploying certificate</code><br><code>Successfully deployed certificate for domain.com to /etc/nginx/conf.d/domain.conf</code><br><code>Successfully deployed certificate for www.domain.com to /etc/nginx/conf.d/domain.conf</code><br><code>Congratulations! You have successfully enabled HTTPS on https://domain.com and https://www.domain.com</code></p><h2 id="压缩与解压" tabindex="-1">压缩与解压 <a class="header-anchor" href="#压缩与解压" aria-label="Permalink to &quot;压缩与解压&quot;">​</a></h2><p>压缩tar.gz</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tar -zcvf archive.tar.gz directory</span></span></code></pre></div><p>解压tar.gz</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tar -zxvf example.tar.gz</span></span></code></pre></div>',25)])])}const b=e(o,[["render",n]]);export{u as __pageData,b as default};
